export function mapPose(pose,sourceW,sourceH,w,h,mirror=true,confidence=.45){if(!pose)return null;const mapping=coverMapping(sourceW,sourceH,w,h,mirror),points=pose.points.map(p=>({...mapping.point(p),visibility:p.visibility??1,presence:p.presence??1}));const arms=[];for(const [arm,si,ei,wi,ii,pi]of [['left',11,13,15,19,17],['right',12,14,16,20,18]]){const valid=visible(pose.points[wi],confidence)&&[ii,pi].some(i=>visible(pose.points[i],confidence));const fingers=[wi,ii,pi].filter(i=>visible(pose.points[i],confidence)).map(i=>points[i]);const hand=fingers.reduce((a,p)=>({x:a.x+p.x/fingers.length,y:a.y+p.y/fingers.length}),{x:0,y:0});arms.push({arm,owner:pose.id,shoulder:points[si],elbow:points[ei],wrist:points[wi],hand,valid});}return{owner:pose.id,center:mapping.point(pose.center),width:pose.width*mapping.dw,points,arms};}
